W=/home/timo/.local/state/worktree/trees/codewandler/ignite-lang/ignite-static; M=/home/timo/.cache/scratch/c7fc37f1-9791-4466-8333-da801f43672c/static/m; rm -rf $M; mkdir -p $M; cd $W; printf 'run\tprogram\ttarget\tlink\tseconds\tbytes\tload1\n'; for run in 1 2 3; do for prog in examples/todo/todo.ignite:todod examples/lsp/server.ignite:ignite-lsp; do src=${prog%%:*}; exe=${prog##*:}; for target in llvm rust; do for link in dynamic static; do out=$M/$run-$exe-$target-$link; flag=""; [ $link = static ] && flag=--static; load=$(cut -d' ' -f1 /proc/loadavg); start=$(date +%s.%N); target/release/ignite build $src --target $target --release --out $out --target-dir $out/target $flag > $out.log 2>&1 || { echo "FAIL $out"; cat $out.log; exit 1; }; end=$(date +%s.%N); path=$(sed -n "s|^built \(.*/$exe\)$|\1|p" $out.log); printf '%s\t%s\t%s\t%s\t%.3f\t%s\t%s\n' $run $exe $target $link $(echo "$end - $start" | bc) $(stat -c %s $path) $load; file $path >> $M/file.txt; done; done; done; done
